import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { startServer, type Running } from "./helpers/server.ts";

interface ApiError {
  error: { code: string; message: string };
}

function postTitle(server: Running, title: unknown): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
}

async function storedTitles(server: Running): Promise<string[]> {
  const body = (await (await fetch(`${server.baseUrl}/api/tasks`)).json()) as {
    tasks: { title: string }[];
  };
  return body.tasks.map((task) => task.title);
}

describe("SL-004 reject empty and over-long titles", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  describe("AC-1: a title that is empty after trimming", () => {
    for (const [label, title] of [
      ["empty", ""],
      ["spaces only", "     "],
      ["tabs and newlines only", " \t\n "],
    ] as const) {
      it(`AC-1: ${label} answers 400 validation_failed 'A title is required.'`, async () => {
        const response = await postTitle(server, title);
        assert.equal(response.status, 400);
        const { error } = (await response.json()) as ApiError;
        assert.equal(error.code, "validation_failed");
        assert.equal(error.message, "A title is required.");
      });
    }

    it("AC-1: a missing or non-string title answers 400 validation_failed 'Title must be a string.'", async () => {
      for (const title of [undefined, null, 42, ["x"]]) {
        const response = await postTitle(server, title);
        assert.equal(response.status, 400);
        const { error } = (await response.json()) as ApiError;
        assert.equal(error.code, "validation_failed");
        assert.equal(error.message, "Title must be a string.");
      }
    });

    it("AC-1: no task is created", async () => {
      assert.deepEqual(await storedTitles(server), []);
    });
  });

  describe("AC-2: a title longer than 500 characters", () => {
    it("AC-2: 501 characters answers 400 validation_failed with the length message", async () => {
      const response = await postTitle(server, "a".repeat(501));
      assert.equal(response.status, 400);
      const { error } = (await response.json()) as ApiError;
      assert.equal(error.code, "validation_failed");
      assert.equal(error.message, "The title is too long (maximum 500 characters).");
    });

    it("AC-2: the length is counted after trimming, so 500 characters plus spaces is accepted", async () => {
      const title = "b".repeat(500);
      const response = await postTitle(server, `  ${title}  `);
      assert.equal(response.status, 201);
      assert.deepEqual(await storedTitles(server), [title]);
    });

    it("AC-2: 501 characters after trimming is rejected even with surrounding spaces", async () => {
      const response = await postTitle(server, ` ${"c".repeat(501)} `);
      assert.equal(response.status, 400);
    });

    it("AC-2: no task was created by the rejected titles", async () => {
      assert.deepEqual(await storedTitles(server), ["b".repeat(500)]);
    });
  });

  describe("the page shows the reason", () => {
    let html: string;
    let script: string;

    before(async () => {
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });

    it("AC-1: has a form-message element with role=alert", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])/);
    });

    it("AC-1: the script shows error.message in form-message with textContent", () => {
      assert.match(script, /form-message/);
      assert.match(script, /error\.message/);
      assert.match(script, /\.textContent\s*=/);
      assert.doesNotMatch(script, /innerHTML/);
    });
  });
});
EOF
